import { Ionicons } from '@expo/vector-icons';
import { useQuery } from '@tanstack/react-query';
import { BlurView } from 'expo-blur';
import { router, useLocalSearchParams } from 'expo-router';
import { useCallback, useState, type ReactNode } from 'react';
import { ActivityIndicator, Platform, Pressable, RefreshControl, ScrollView, StatusBar, Text, View } from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';

import { EmptyState } from '@/components/empty-state';
import { CachedImage } from '@/components/cached-image';
import { PageHeader } from '@/components/layout/page-header';
import { SkeletonLoader } from '@/components/skeleton-loader';
import { typography } from '@/constants/typography';
import { getCategoryEyebrow } from '@/features/drills/drill-media';
import { PlaceholderBanner } from '@/features/drills/components/placeholder-banner';
import { isRecoverableApiError } from '@/lib/api-client';
import { drillsService } from '@/services';
import { useAppStore } from '@/store/app-store';

function FrostedCard({ children }: { children: ReactNode }) {
  if (Platform.OS === 'android') {
    return <View style={{ backgroundColor: 'rgba(250, 246, 240, 0.92)' }}>{children}</View>;
  }

  return (
    <BlurView
      intensity={60}
      tint="systemThickMaterialLight"
      style={{ backgroundColor: 'rgba(255, 255, 255, 0.15)' }}
    >
      <View style={{ backgroundColor: 'rgba(250, 246, 240, 0.65)' }}>{children}</View>
    </BlurView>
  );
}

export default function DrillCategoryScreen() {
  const { slug } = useLocalSearchParams<{ slug: string }>();
  const routeSlug = slug ?? '';
  const isPremium = useAppStore((state) => state.isPremium);
  const [imageLoading, setImageLoading] = useState(true);
  const insets = useSafeAreaInsets();

  const categoryQuery = useQuery({
    queryKey: ['drill-category', routeSlug],
    queryFn: () => drillsService.getCategory(routeSlug),
  });

  const freeDrillsQuery = useQuery({
    queryKey: ['drill-list', routeSlug, 'free'],
    queryFn: () => drillsService.getDrillsByCategoryAndAccessLevel(routeSlug, 'free'),
  });

  const premiumDrillsQuery = useQuery({
    queryKey: ['drill-list', routeSlug, 'premium'],
    queryFn: () => drillsService.getDrillsByCategoryAndAccessLevel(routeSlug, 'premium'),
  });

  const isRefreshing =
    categoryQuery.isFetching || freeDrillsQuery.isFetching || premiumDrillsQuery.isFetching;

  const refreshCategory = useCallback(async () => {
    await Promise.all([
      categoryQuery.refetch(),
      freeDrillsQuery.refetch(),
      premiumDrillsQuery.refetch(),
    ]);
  }, [categoryQuery, freeDrillsQuery, premiumDrillsQuery]);

  if (categoryQuery.isLoading || freeDrillsQuery.isLoading || premiumDrillsQuery.isLoading) {
    return (
      <View style={{ flex: 1, backgroundColor: '#F4E7D5', paddingTop: insets.top }}>
        <SkeletonLoader />
      </View>
    );
  }

  if (
    (!categoryQuery.data || !freeDrillsQuery.data || !premiumDrillsQuery.data) &&
    (
      isRecoverableApiError(categoryQuery.error) ||
      isRecoverableApiError(freeDrillsQuery.error) ||
      isRecoverableApiError(premiumDrillsQuery.error)
    )
  ) {
    return (
      <View style={{ flex: 1, backgroundColor: '#F4E7D5', paddingTop: insets.top }}>
        <SkeletonLoader />
      </View>
    );
  }

  if (categoryQuery.error || freeDrillsQuery.error || premiumDrillsQuery.error || !categoryQuery.data) {
    return (
      <View style={{ flex: 1, backgroundColor: '#F4E7D5', paddingTop: insets.top, paddingHorizontal: 16, justifyContent: 'center' }}>
        <EmptyState
          title="Could not load drills"
          description={
            categoryQuery.error?.message ??
            freeDrillsQuery.error?.message ??
            premiumDrillsQuery.error?.message ??
            'Request failed'
          }
        />
      </View>
    );
  }

  const category = categoryQuery.data;
  const freeDrills = freeDrillsQuery.data ?? [];
  const premiumDrills = premiumDrillsQuery.data ?? [];
  const hasAnyDrills = freeDrills.length > 0 || premiumDrills.length > 0;
  const categoryImageSource = category.image && /^https?:\/\//.test(category.image)
    ? { uri: category.image }
    : null;

  return (
    <View style={{ flex: 1, backgroundColor: '#F4E7D5' }}>
      <PageHeader
        title={category.name}
        variant="section"
        rightSlot={(
          <Pressable style={{ height: 36, width: 36, alignItems: 'center', justifyContent: 'center' }}>
            <Ionicons color="#1F3A5F" name="search" size={22} />
          </Pressable>
        )}
      />

      <ScrollView
        showsVerticalScrollIndicator={false}
        contentContainerStyle={{ paddingBottom: 100 }}
        refreshControl={(
          <RefreshControl
            colors={['#E35D21']}
            onRefresh={refreshCategory}
            refreshing={isRefreshing}
            tintColor="#E35D21"
          />
        )}
      >
        <View>
          <View style={{ paddingHorizontal: 16, paddingVertical: 24 }}>
            {/* Top Eyebrow Section */}
            <View style={{ marginBottom: 20 }}>
              <Text style={{ fontSize: 10, fontWeight: '700', color: '#C2410C', letterSpacing: 1.5, textTransform: 'uppercase', marginBottom: 6 }}>
                {getCategoryEyebrow(category.name)}
              </Text>
              <Text style={{ fontSize: 44, fontWeight: '900', textTransform: 'uppercase', lineHeight: 46, color: '#1A1A1A', fontFamily: typography.family.serif }}>
                {category.name}
              </Text>
              <Text style={{ marginTop: 8, fontSize: 15, lineHeight: 22, color: '#5A4B3D', fontWeight: '400' }}>
                {category.subtitle}
              </Text>
            </View>

            {/* Featured Image */}
            {categoryImageSource ? (
              <View style={{ marginBottom: 28, borderRadius: 28, overflow: 'hidden', backgroundColor: '#FFFFFF', shadowColor: '#000', shadowOpacity: 0.08, shadowRadius: 15, shadowOffset: { width: 0, height: 6 }, elevation: 4, height: 210, justifyContent: 'center', alignItems: 'center' }}>
                <CachedImage
                  uri={categoryImageSource.uri}
                  style={{ width: '100%', height: 210, position: 'absolute' }}
                  contentFit="cover"
                  transition={250}
                  onLoadStart={() => setImageLoading(true)}
                  onLoadEnd={() => setImageLoading(false)}
                />
                {imageLoading && (
                  <ActivityIndicator size="small" color="#C2410C" />
                )}
              </View>
            ) : (
              <View style={{ marginBottom: 28 }}>
                <PlaceholderBanner title={category.name} subtitle={`${category.numberOfDrills} drills`} />
              </View>
            )}

            {!hasAnyDrills ? (
              <View style={{ marginBottom: 24 }}>
                <EmptyState
                  title="No drills yet"
                  description="When drills are added from the admin dashboard, they will appear here automatically."
                />
              </View>
            ) : null}

            {/* Included Drills Section */}
            {freeDrills.length ? (
            <View style={{ marginBottom: 32 }}>
              <View style={{ flexDirection: 'row', alignItems: 'center', marginBottom: 14 }}>
                <View style={{ backgroundColor: '#FAF0E6', paddingHorizontal: 8, paddingVertical: 3, borderRadius: 5, marginRight: 10 }}>
                  <Text style={{ fontSize: 9, fontWeight: '800', color: '#A34712', textTransform: 'uppercase', letterSpacing: 0.8 }}>Included</Text>
                </View>
                <Text style={{ fontSize: 20, fontWeight: '800', color: '#1A1A1A', fontFamily: typography.family.serif }}>Included Drills</Text>
              </View>

              <View style={{ gap: 12 }}>
                {freeDrills.map((drill) => {
                  const iconName = (drill.listIcon || 'baseball-outline') as any;

                  return (
                    <Pressable
                      key={drill.id}
                      onPress={() => router.push(`/drills/detail/${drill.id}`)}
                      style={{ flexDirection: 'row', alignItems: 'center', backgroundColor: '#FFFFFF', borderRadius: 20, paddingHorizontal: 18, paddingVertical: 16, shadowColor: '#000', shadowOpacity: 0.04, shadowRadius: 10, shadowOffset: { width: 0, height: 4 }, elevation: 2, borderWidth: 1, borderColor: '#F0E8DB' }}
                    >
                      <View style={{ height: 40, width: 40, borderRadius: 20, backgroundColor: '#FAF4EA', alignItems: 'center', justifyContent: 'center', marginRight: 14 }}>
                        <Ionicons name={iconName} size={20} color="#C2410C" />
                      </View>
                      <Text style={{ flex: 1, fontSize: 17, fontWeight: '700', color: '#1F2937' }}>{drill.name}</Text>
                      <Ionicons name="chevron-forward" size={18} color="#CBD2E0" />
                    </Pressable>
                  );
                })}
              </View>
            </View>
            ) : null}

            {/* Premium Drills Section */}
            {premiumDrills.length ? (
            <View style={{ marginBottom: 24 }}>
              <View style={{ flexDirection: 'row', alignItems: 'center', marginBottom: 14 }}>
                <View style={{ backgroundColor: '#FFF7ED', paddingHorizontal: 8, paddingVertical: 3, borderRadius: 5, marginRight: 10, borderWidth: 1, borderColor: '#FFEDD5' }}>
                  <Text style={{ fontSize: 9, fontWeight: '800', color: '#C2410C', textTransform: 'uppercase', letterSpacing: 0.8 }}>Premium</Text>
                </View>
                <Text style={{ fontSize: 20, fontWeight: '800', color: '#1A1A1A', fontFamily: typography.family.serif }}>Premium Drills</Text>
              </View>

              <View style={{ gap: 12 }}>
                {premiumDrills.map((drill) => (
                  <Pressable
                    key={drill.id}
                    onPress={() => isPremium ? router.push(`/drills/detail/${drill.id}`) : router.push('/payment')}
                    style={{ flexDirection: 'row', alignItems: 'center', backgroundColor: '#FFFFFF', borderRadius: 20, paddingHorizontal: 18, paddingVertical: 16, shadowColor: '#000', shadowOpacity: 0.04, shadowRadius: 10, shadowOffset: { width: 0, height: 4 }, elevation: 2, borderWidth: 1, borderColor: '#F0E8DB' }}
                  >
                    <View
                      style={{
                        height: 40,
                        width: 40,
                        borderRadius: 20,
                        backgroundColor: isPremium ? '#FAF4EA' : '#F5F5F5',
                        alignItems: 'center',
                        justifyContent: 'center',
                        marginRight: 14,
                        opacity: isPremium ? 1 : 0.6,
                      }}
                    >
                      <Ionicons
                        name={(isPremium ? drill.listIcon : 'lock-closed') as any}
                        size={18}
                        color={isPremium ? '#C2410C' : '#CBD2E0'}
                      />
                    </View>
                    <Text
                      style={{
                        flex: 1,
                        fontSize: 17,
                        fontWeight: '700',
                        color: '#1F2937',
                        opacity: isPremium ? 1 : 0.6,
                      }}
                    >
                      {drill.name}
                    </Text>
                    <Ionicons name="chevron-forward" size={18} color="#CBD2E0" />
                  </Pressable>
                ))}
              </View>
            </View>
            ) : null}

            {/* Unlock All Section Card (Glassmorphism) */}
            {!isPremium && premiumDrills.length > 0 && (
              <View style={{ marginTop: 12, borderRadius: 28, overflow: 'hidden', shadowColor: '#000', shadowOpacity: 0.1, shadowRadius: 24, shadowOffset: { width: 0, height: 12 }, elevation: 8, borderWidth: 1, borderColor: 'rgba(255,255,255,0.6)' }}>
                <FrostedCard>
                    <View
                      style={{
                        paddingHorizontal: 20,
                        paddingVertical: 32,
                        alignItems: 'center',
                        justifyContent: 'center'
                      }}
                    >
                      <View style={{ height: 48, width: 48, borderRadius: 24, backgroundColor: '#E35D21', alignItems: 'center', justifyContent: 'center', marginBottom: 12 }}>
                        <Ionicons color="#FFFFFF" name="lock-closed" size={22} />
                      </View>
                      <Text style={{ textAlign: 'center', fontSize: 24, fontWeight: '900', lineHeight: 28, color: '#1A1A1A', fontFamily: typography.family.serif, marginBottom: 16 }}>
                        Unlock all drills
                      </Text>
                      <Text style={{ textAlign: 'center', fontSize: 14, lineHeight: 22, color: '#374151', fontWeight: '600', marginBottom: 28, paddingHorizontal: 10 }}>
                        Get access to our full library of 50+ professional hitting and fielding drills.
                      </Text>
                      <Pressable onPress={() => router.push('/payment')} style={{ width: '100%', height: 60, borderRadius: 30, backgroundColor: '#E35D21', justifyContent: 'center', alignItems: 'center', shadowColor: '#E35D21', shadowOpacity: 0.2, shadowRadius: 10, shadowOffset: { width: 0, height: 4 }, elevation: 4 }}>
                        <Text style={{ fontSize: 16, fontWeight: '800', color: '#FFFFFF', textTransform: 'uppercase', letterSpacing: 1 }}>View Plans</Text>
                      </Pressable>
                    </View>
                </FrostedCard>
              </View>
            )}
          </View>
        </View>
      </ScrollView>
    </View>
  );
}

import { Ionicons } from '@expo/vector-icons';
import { useQuery } from '@tanstack/react-query';
import { router } from 'expo-router';
import { useCallback, useRef, useState } from 'react';
import {
  FlatList,
  NativeScrollEvent,
  NativeSyntheticEvent,
  Platform,
  Pressable,
  RefreshControl,
  ScrollView,
  StatusBar,
  Text,
  useWindowDimensions,
  View,
} from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';

import { EmptyState } from '@/components/empty-state';
import { SkeletonLoader } from '@/components/skeleton-loader';
import { CachedImage } from '@/components/cached-image';
import { getActiveApiBaseUrl, isRecoverableApiError } from '@/lib/api-client';
import { drillsService, featuredSituationsService, settingsService, situationsService } from '@/services';
import { useAppStore } from '@/store/app-store';
import type { Drill, Situation } from '@/types';
import HomeLogo from '../../../assets/svg/home-logo.svg';

export default function HomeScreen() {
  const { width } = useWindowDimensions();
  const insets = useSafeAreaInsets();
  const statusBarHeight = insets.top;
  const isPremium = useAppStore((state) => state.isPremium);
  const sliderRef = useRef<FlatList<Situation>>(null);
  const [activeSlide, setActiveSlide] = useState(0);
  const [lastRandomSituationId, setLastRandomSituationId] = useState<string | null>(null);
  const [isRefreshing, setIsRefreshing] = useState(false);

  const {
    data: situations,
    isLoading: situationsLoading,
    error: situationsError,
    isFetching: situationsFetching,
    refetch: refetchSituations,
  } = useQuery({
    queryKey: ['situations'],
    queryFn: situationsService.getAll,
  });
  const {
    data: appSettings,
    isLoading: settingsLoading,
    error: settingsError,
    isFetching: settingsFetching,
    refetch: refetchSettings,
  } = useQuery({
    queryKey: ['app-settings'],
    queryFn: settingsService.getAppSettings,
  });
  const {
    data: backendFeaturedSituations,
    isFetching: featuredFetching,
    refetch: refetchFeaturedSituations,
  } = useQuery({
    queryKey: ['featured-situations'],
    queryFn: featuredSituationsService.getAll,
  });
  const {
    data: newDrills,
    isLoading: newDrillsLoading,
    error: newDrillsError,
    isFetching: newDrillsFetching,
    refetch: refetchNewDrills,
  } = useQuery({
    queryKey: ['new-drills'],
    queryFn: () => drillsService.getNewDrills(5),
    retry: 1,
  });
  const refreshHome = useCallback(async () => {
    setIsRefreshing(true);

    try {
      await Promise.all([
        refetchSituations(),
        refetchSettings(),
        refetchFeaturedSituations(),
        refetchNewDrills(),
      ]);
    } finally {
      setIsRefreshing(false);
    }
  }, [refetchFeaturedSituations, refetchNewDrills, refetchSettings, refetchSituations]);

  const isInitialRecoverableError =
    (!situations || !appSettings) &&
    (isRecoverableApiError(situationsError) || isRecoverableApiError(settingsError));

  if (situationsLoading || settingsLoading || isInitialRecoverableError) {
    return (
      <View style={{ flex: 1, backgroundColor: '#F4E7D5', paddingTop: statusBarHeight }}>
        <SkeletonLoader />
      </View>
    );
  }

  if (situationsError || settingsError || !situations || !appSettings) {
    return (
      <View style={{ flex: 1, backgroundColor: '#F4E7D5', paddingTop: statusBarHeight, paddingHorizontal: 16, justifyContent: 'center' }}>
        <EmptyState
          title="Could not load home"
          description={`${situationsError?.message ?? settingsError?.message ?? 'Request failed'}\nAPI: ${getActiveApiBaseUrl()}`}
        />
      </View>
    );
  }

  const featuredSituations = backendFeaturedSituations?.length
    ? backendFeaturedSituations
    : (situations || []).filter((item) => item.featured);
  const sliderItems = featuredSituations.length ? featuredSituations : (situations || []);
  const specificSituation = (situations || []).find((item) => !item.featured) ?? (situations || [])[0];
  const bulletItems = specificSituation?.instructions?.slice(0, 9) || [];
  const specificSituationImageUri = specificSituation?.imageUrl || specificSituation?.image;
  const slideWidth = width - 32;
  const situationCountLabel = situations.length > 99 ? '99+' : String(situations.length);
  const renderNewDrill = (drill: Drill) => (
    <Pressable
      key={drill.id}
      onPress={() => {
        if (drill.accessLevel === 'premium' && !isPremium) {
          router.push('/payment');
          return;
        }

        router.push(`/drills/detail/${drill.id}`);
      }}
      style={{ flexDirection: 'row', alignItems: 'center', borderRadius: 18, backgroundColor: '#FFFFFF', padding: 12, shadowColor: '#000', shadowOpacity: 0.04, shadowRadius: 8, shadowOffset: { width: 0, height: 3 }, elevation: 2 }}
    >
      {drill.image ? (
        <CachedImage
          contentFit="cover"
          uri={drill.image}
          style={{ height: 54, width: 72, borderRadius: 14, backgroundColor: '#F8F2E8' }}
        />
      ) : (
        <View style={{ height: 54, width: 72, borderRadius: 14, backgroundColor: '#F8F2E8', alignItems: 'center', justifyContent: 'center' }}>
          <Ionicons color="#C2410C" name={(drill.listIcon || 'baseball-outline') as any} size={22} />
        </View>
      )}
      <View style={{ flex: 1, marginLeft: 12 }}>
        <Text style={{ fontSize: 16, fontWeight: '800', color: '#21314F' }}>{drill.name}</Text>
        <Text style={{ marginTop: 3, fontSize: 12, fontWeight: '600', color: '#7B6D5C' }}>{drill.category}</Text>
      </View>
      <Ionicons color="#CBD2E0" name="chevron-forward" size={18} />
    </Pressable>
  );

  const handleSliderScroll = (event: NativeSyntheticEvent<NativeScrollEvent>) => {
    const nextIndex = Math.round(event.nativeEvent.contentOffset.x / slideWidth);
    if (nextIndex !== activeSlide) {
      setActiveSlide(nextIndex);
    }
  };

  const scrollToSlide = (direction: 'prev' | 'next') => {
    const maxIndex = sliderItems.length - 1;
    const nextIndex =
      direction === 'prev' ? Math.max(activeSlide - 1, 0) : Math.min(activeSlide + 1, maxIndex);

    sliderRef.current?.scrollToOffset({
      animated: true,
      offset: nextIndex * slideWidth,
    });
    setActiveSlide(nextIndex);
  };

  const openRandomSituation = () => {
    const randomPool =
      situations.length > 1
        ? situations.filter((situation) => situation.id !== lastRandomSituationId)
        : situations;
    const randomSituation = randomPool[Math.floor(Math.random() * randomPool.length)];
    setLastRandomSituationId(randomSituation.id);
    router.push(`/situations/${randomSituation.id}`);
  };

  return (
    <View style={{ flex: 1, backgroundColor: '#F4E7D5' }}>
      {/* ===== NAVBAR (Fixed) ===== */}
      <View
        style={{
          paddingTop: statusBarHeight,
          backgroundColor: '#FFFFFF',
          borderBottomWidth: 1,
          borderColor: '#EFE7D9',
        }}
      >
        <View
          style={{
            flexDirection: 'row',
            alignItems: 'center',
            justifyContent: 'space-between',
            paddingHorizontal: 16,
            paddingVertical: 12,
          }}
        >
          <View>
            <Text
              style={{
                fontSize: 20,
                fontWeight: '700',
                color: '#0C1F4A',
                fontFamily: 'serif',
                fontStyle: 'italic',
              }}
            >
              Marietta
            </Text>
            <Text
              style={{
                fontSize: 10,
                fontWeight: '600',
                color: '#0C1F4A',
                textTransform: 'uppercase',
                letterSpacing: 1.2,
                marginTop: 1,
              }}
            >
              Baseball Academy
            </Text>
          </View>
          <Pressable style={{ height: 36, width: 36, alignItems: 'center', justifyContent: 'center' }}>
            <Ionicons color="#0C1F4A" name="search" size={20} />
          </Pressable>
        </View>
      </View>

      <ScrollView
        showsVerticalScrollIndicator={false}
        contentContainerStyle={{ paddingBottom: 120 }}
        refreshControl={(
          <RefreshControl
            colors={['#E35D21']}
            onRefresh={refreshHome}
            refreshing={isRefreshing}
            tintColor="#E35D21"
          />
        )}
      >

        {/* ===== HERO SECTION ===== */}
        <View style={{ position: 'relative', overflow: 'hidden', backgroundColor: '#F4E7D5' }}>
          {/* Grid pattern */}
          <View style={{ position: 'absolute', top: 0, left: 0, right: 0, bottom: 0, opacity: 0.3 }}>
            {[0, 80, 160, 240, 320, 400, 480].map(top => (
              <View key={top} style={{ position: 'absolute', left: 0, right: 0, top, height: 1.5, backgroundColor: '#D8C3A6' }} />
            ))}
            {(['20%', '40%', '60%', '80%'] as const).map(left => (
              <View key={left} style={{ position: 'absolute', top: 0, bottom: 0, left: left as any, width: 1.5, backgroundColor: '#D8C3A6' }} />
            ))}
          </View>

          <View style={{ paddingHorizontal: 20, paddingTop: 20, paddingBottom: 24 }}>
            <Text style={{ textAlign: 'center', fontSize: 11, lineHeight: 14, fontWeight: '700', color: '#5A4B3D', letterSpacing: 1.5, textTransform: 'uppercase' }}>{appSettings.homeEyebrow}</Text>
            <Text style={{ marginTop: 4, textAlign: 'center', fontSize: 40, fontWeight: '900', textTransform: 'uppercase', lineHeight: 42, color: '#1A1A1A', fontFamily: 'serif' }}>{appSettings.homeTitle}</Text>
            <View style={{ marginTop: 12, alignItems: 'center' }}><HomeLogo height={110} width={138} /></View>
            <Pressable style={{ marginTop: 20, height: 46, borderRadius: 999, backgroundColor: '#E35D21', justifyContent: 'center', alignItems: 'center' }} onPress={openRandomSituation}>
              <Text style={{ fontSize: 15, fontWeight: '700', color: '#FFFFFF' }}>Pick Random</Text>
            </Pressable>
            <Pressable style={{ marginTop: 10, height: 46, borderRadius: 999, backgroundColor: '#E35D21', justifyContent: 'center', alignItems: 'center' }} onPress={() => router.push('/(tabs)/situations')}>
              <Text style={{ fontSize: 15, fontWeight: '700', color: '#FFFFFF' }}>{`Browse All ${situationCountLabel}`}</Text>
            </Pressable>
          </View>
        </View>

        {/* ===== FEATURED SITUATION ===== */}
        <View style={{ backgroundColor: '#F4E7D5', paddingHorizontal: 16, paddingTop: 16, paddingBottom: 20 }}>
          <View style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', marginBottom: 10 }}>
            <Text style={{ fontSize: 10, fontWeight: '700', letterSpacing: 1.0, color: '#9F927A', textTransform: 'uppercase' }}>Featured Situation</Text>
            <View style={{ flexDirection: 'row', gap: 8 }}>
              <Pressable style={{ height: 30, width: 30, alignItems: 'center', justifyContent: 'center', borderRadius: 15, borderWidth: 1, borderColor: '#E6D8BF', backgroundColor: '#FFFFFF' }} disabled={activeSlide === 0} onPress={() => scrollToSlide('prev')}>
                <Ionicons color={activeSlide === 0 ? '#D0C4AF' : '#D66A1D'} name="chevron-back" size={14} />
              </Pressable>
              <Pressable style={{ height: 30, width: 30, alignItems: 'center', justifyContent: 'center', borderRadius: 15, borderWidth: 1, borderColor: '#E6D8BF', backgroundColor: '#FFFFFF' }} disabled={activeSlide === sliderItems.length - 1} onPress={() => scrollToSlide('next')}>
                <Ionicons color={activeSlide === sliderItems.length - 1 ? '#D0C4AF' : '#D66A1D'} name="chevron-forward" size={14} />
              </Pressable>
            </View>
          </View>

          <FlatList
            ref={sliderRef}
            data={sliderItems}
            horizontal
            keyExtractor={(item) => item.id}
            onMomentumScrollEnd={handleSliderScroll}
            pagingEnabled
            showsHorizontalScrollIndicator={false}
            snapToAlignment="start"
            snapToInterval={slideWidth}
            decelerationRate="fast"
            renderItem={({ item }) => (
