import { useState } from 'react';
import type { ComponentType } from 'react';
import {
  ActivityIndicator,
  Linking,
  Pressable,
  Text,
  View,
  useWindowDimensions,
} from 'react-native';
import type { WebViewProps } from 'react-native-webview';

import { CachedImage } from '@/components/cached-image';
import { colors } from '@/constants/theme';
import { extractYouTubeVideoId } from '@/features/drills/youtube';

type YouTubeVideoProps = {
  url?: string | null;
};

let cachedWebView: ComponentType<WebViewProps> | null | undefined;

export const getYouTubeWebView = () => {
  if (cachedWebView !== undefined) return cachedWebView;

  try {
    cachedWebView = require('react-native-webview').WebView as ComponentType<WebViewProps>;
  } catch {
    cachedWebView = null;
  }

  return cachedWebView;
};

export const YouTubeVideo = ({ url }: YouTubeVideoProps) => {
  const videoId = extractYouTubeVideoId(url);
  const { width } = useWindowDimensions();
  const [isLoading, setIsLoading] = useState(true);
  const [hasError, setHasError] = useState(false);
  const [embedBlocked, setEmbedBlocked] = useState(false);
  const WebView = getYouTubeWebView();

  if (!videoId || !WebView || hasError) return null;

  const videoWidth = Math.max(width - 40, 0);
  const watchUrl = `https://www.youtube.com/watch?v=${videoId}`;
  const thumbnailUrl = `https://img.youtube.com/vi/${videoId}/hqdefault.jpg`;
  const embedUrl =
    `https://www.youtube-nocookie.com/embed/${videoId}` +
    '?playsinline=1&rel=0&modestbranding=1' +
    '&origin=https%3A%2F%2Fwww.youtube-nocookie.com' +
    '&widget_referrer=https%3A%2F%2Fwww.youtube-nocookie.com%2F';
  const detectYouTubeErrorScript = `
    (function detectYouTubeError() {
      var text = document.body && document.body.innerText ? document.body.innerText : '';
      if (/Error code:\\s*(15|150|152|153)|This video is unavailable|Video player configuration error/i.test(text)) {
        window.ReactNativeWebView.postMessage('youtube-embed-blocked');
      }
      setTimeout(detectYouTubeError, 1000);
    })();
    true;
  `;

  if (embedBlocked) {
    return (
      <Pressable
        accessibilityRole="button"
        className="overflow-hidden rounded-[18px] bg-black"
        onPress={() => {
          void Linking.openURL(watchUrl);
        }}
        style={{ width: videoWidth, height: videoWidth * 0.5625 }}
      >
        <View className="h-full w-full items-center justify-center">
          <CachedImage
            contentFit="cover"
            uri={thumbnailUrl}
            style={{ position: 'absolute', inset: 0 }}
          />
          <View className="absolute inset-0 bg-black/45" />
          <View className="h-14 w-14 items-center justify-center rounded-full bg-white/90">
            <View className="ml-1 h-0 w-0 border-y-[10px] border-l-[16px] border-y-transparent border-l-[#0C1F4A]" />
          </View>
          <Text className="mt-3 text-sm font-bold text-white">Watch on YouTube</Text>
        </View>
      </Pressable>
    );
  }

  return (
    <View
      className="overflow-hidden rounded-[18px] bg-black"
      style={{ width: videoWidth, height: videoWidth * 0.5625 }}
    >
      <WebView
        allowsFullscreenVideo
        allowsInlineMediaPlayback
        androidLayerType="hardware"
        javaScriptEnabled
        domStorageEnabled
        mediaPlaybackRequiresUserAction
        injectedJavaScript={detectYouTubeErrorScript}
        onMessage={(event) => {
          if (event.nativeEvent.data === 'youtube-embed-blocked') {
            setEmbedBlocked(true);
          }
        }}
        onError={() => setHasError(true)}
        onHttpError={() => setHasError(true)}
        onLoadEnd={() => setIsLoading(false)}
        originWhitelist={['https://*']}
        scrollEnabled={false}
        source={{
          uri: embedUrl,
          headers: {
            Referer: 'https://www.youtube-nocookie.com/',
          },
        }}
        style={{ backgroundColor: 'black' }}
        userAgent="Mozilla/5.0 (Linux; Android 10; Mobile) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Mobile Safari/537.36"
      />
      {isLoading ? (
        <View className="absolute inset-0 items-center justify-center bg-black">
          <ActivityIndicator color={colors.orange} />
        </View>
      ) : null}
    </View>
  );
};

import { Directory, File, Paths } from 'expo-file-system';

const imageCacheDirectory = new Directory(Paths.cache, 'mba-images');

const ensureImageCacheDirectory = () => {
  if (!imageCacheDirectory.exists) {
    imageCacheDirectory.create({ idempotent: true, intermediates: true });
  }
};

const hashValue = (value: string) => {
  let hash = 5381;

  for (let index = 0; index < value.length; index += 1) {
    hash = ((hash << 5) + hash) ^ value.charCodeAt(index);
  }

  return Math.abs(hash).toString(36);
};

const getExtension = (value: string) => {
  try {
    const url = new URL(value);
    const extension = url.pathname.split('.').pop()?.trim().toLowerCase();

    if (extension && /^[a-z0-9]{2,5}$/.test(extension)) {
      return extension;
    }
  } catch {
    // Ignore malformed urls and fall back to a generic extension.
  }

  return 'img';
};

const getCachedImageFile = (uri: string) =>
  new File(imageCacheDirectory, `${hashValue(uri)}.${getExtension(uri)}`);

export const isRemoteImageUri = (uri?: string | null) => /^https?:\/\//i.test(uri?.trim() ?? '');

export async function getCachedImageUri(uri?: string | null): Promise<string> {
  const normalizedUri = uri?.trim() ?? '';

  if (!isRemoteImageUri(normalizedUri)) {
    return normalizedUri;
  }

  try {
    ensureImageCacheDirectory();
    const file = getCachedImageFile(normalizedUri);
    return file.exists ? file.uri : normalizedUri;
  } catch {
    return normalizedUri;
  }
}

export async function cacheRemoteImage(
  uri?: string | null,
  options?: { forceRefresh?: boolean },
): Promise<string> {
  const normalizedUri = uri?.trim() ?? '';

  if (!isRemoteImageUri(normalizedUri)) {
    return normalizedUri;
  }

  try {
    ensureImageCacheDirectory();
    const file = getCachedImageFile(normalizedUri);

    if (file.exists && !options?.forceRefresh) {
      return file.uri;
    }

    await File.downloadFileAsync(normalizedUri, file, { idempotent: true });
    return file.uri;
  } catch {
    return getCachedImageUri(normalizedUri);
  }
}

export async function warmRemoteImages(
  uris: Array<string | null | undefined>,
  options?: { forceRefresh?: boolean },
): Promise<void> {
  const uniqueUris = Array.from(
    new Set(uris.map((uri) => uri?.trim() ?? '').filter((uri) => isRemoteImageUri(uri))),
  );

  await Promise.allSettled(uniqueUris.map((uri) => cacheRemoteImage(uri, options)));
}
